CREATE TABLE IF NOT EXISTS "custom_contract" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "indebted_name" varchar(64) DEFAULT '',
    "indebted_id" varchar(128) DEFAULT '',
    "creditor_name" varchar(64) DEFAULT '',
    "creditor_id" varchar(128) DEFAULT '',
    "description" varchar(512) DEFAULT '',
    "status" int DEFAULT 0,
    "return_type" int DEFAULT 0,
    "reason_type" int DEFAULT 0,
    "detail_reason" varchar(512) DEFAULT '',
    "salary" double DEFAULT 0.0,
    "tariff" double DEFAULT 0.0,
    "interest" double DEFAULT 0.0,
    "refund" double DEFAULT 0.0,
    "file" varchar(512) DEFAULT '',
    "dept_id" bigint DEFAULT NULL,
    "start_date" datetime DEFAULT NULL,
    "end_date" datetime DEFAULT NULL,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    "creator" varchar(64) DEFAULT '',
    "create_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted" bit(1) NOT NULL DEFAULT FALSE,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "system_users" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "username" varchar(30) NOT NULL,
    "password" varchar(100) NOT NULL DEFAULT '',
    "nickname" varchar(30) NOT NULL DEFAULT '',
    "remark" varchar(500) DEFAULT NULL,
    "dept_id" bigint DEFAULT NULL,
    "post_ids" varchar(255) DEFAULT '',
    "email" varchar(50) DEFAULT '',
    "mobile" varchar(11) DEFAULT '',
    "sex" tinyint DEFAULT '0',
    "avatar" varchar(512) DEFAULT '',
    "status" tinyint NOT NULL DEFAULT '0',
    "login_ip" varchar(50) DEFAULT '',
    "login_date" timestamp NULL DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted" bit(1) NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    "id_no" varchar(128) DEFAULT '',
    "verified" tinyint DEFAULT 0,
    "realname" varchar(64) DEFAULT '',
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "system_role" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(30) NOT NULL,
    "code" varchar(100) NOT NULL,
    "sort" int NOT NULL,
    "data_scope" tinyint NOT NULL DEFAULT '1',
    "data_scope_dept_ids" varchar(500) NOT NULL DEFAULT '',
    "status" tinyint NOT NULL,
    "type" tinyint NOT NULL,
    "remark" varchar(500) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted" bit(1) NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);

CREATE TABLE IF NOT EXISTS "system_user_role" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "role_id" bigint NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted" bit(1) NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
);
